python3 -c "
import pandas as pd
import re

df_time = pd.read_csv('/app/dataset/timesheet.csv')
df_emp = pd.read_csv('/app/dataset/employees.csv')
df_tasks = pd.read_csv('/app/dataset/tasks.csv')
task_pay = dict(zip(df_tasks['task_id'], df_tasks['pay_per_completion']))

emp_pos = dict(zip(df_emp['PESEL'].astype(str).str.zfill(11), df_emp['position']))

def parse_tasks(val):
    if not isinstance(val, str):
        return []
    return [int(x) for x in re.findall(r'\d+', val)]

tasks_by_pos = {}
for idx, row in df_time.iterrows():
    p = str(row['employee_id']).zfill(11)
    if p not in emp_pos:
        continue
    pos = emp_pos[p]
    tasks = parse_tasks(row['performed_tasks'])
    for t in tasks:
        if t in task_pay:
            tasks_by_pos.setdefault(pos, set()).add(t)

for pos, t_set in tasks_by_pos.items():
    print(f'{pos}: {len(t_set)} tasks: {sorted(t_set)}')
"
